}

hide_stderr() {
  out="$(mktempd)/hideout"
  capcode "$@" 2>"$out"
  if [ "$code" -eq 0 ]; then
    return
  fi
  cat "$out" >&2
  return "$code"
}

echo_dur() {
  local dur=$1
  local h=$((dur/60/60))
  local m=$((dur/60%60))
  local s=$((dur%60))
  printf '%dh%dm%ds' "$h" "$m" "$s"
}

sponge() {
  dst="$1"
  tmp="$(mktempd)/sponge"
  cat > "$tmp"
  cat "$tmp" > "$dst"
}

stripansi() {
  # First regex gets rid of standard xterm escape sequences for controlling
  # visual attributes.
  # The second regex I'm not 100% sure, the reference says it selects the US
  # encoding but I'm not sure why that's necessary or why it always occurs
  # in tput sgr0 before the standard escape sequence.
  # See tput sgr0 | xxd
  sed -e $'s/\x1b\[[0-9;]*m//g' -e $'s/\x1b(.//g'
}

runtty() {
  case "$(uname)" in
    Darwin)
      script -q /dev/null "$@"
      ;;
    Linux)
      script -eqc "$*"
      ;;
    *)
      echoerr "runtty: unsupported OS $(uname)"
      return 1
  esac
}

capcode() {
  set +e
  "$@"
  code=$?
  set -e
}

strjoin() {
  (IFS="$1"; shift; echo "$*")
}
#!/bin/sh
if [ "${LIB_FLAG-}" ]; then
  return 0
fi
LIB_FLAG=1

# flag_parse implements a robust flag parser.
#
# For a full fledge example see ../examples/date.sh
#
# It differs from getopts(1) in that long form options are supported. Currently the only
# deficiency is that short combined options are not supported like -xyzq. That would be
# interpreted as a single -xyzq flag. The other deficiency is lack of support for short
# flag syntax like -carg where the arg is not separated from the flag. This one is
# unfixable I believe unfortunately but for combined short flags I have opened
# https://github.com/d2lang/ci/issues/6
#
# flag_parse stores state in $FLAG, $FLAGRAW, $FLAGARG and $FLAGSHIFT.
# FLAG contains the name of the flag without hyphens.
# FLAGRAW contains the name of the flag as passed in with hyphens.
# FLAGARG contains the argument for the flag if there was any.
#   If there was none, it will not be set.
# FLAGSHIFT contains the number by which the arguments should be shifted to
#   start at the next flag/argument
#
# flag_parse exits with a non zero code when there are no more flags
# to be parsed. Still, call shift "$FLAGSHIFT" in case there was a --
#
# If the argument for the flag is optional, then use ${FLAGARG-} to access
# the argument if one was passed. Use ${FLAGARG+x} = x to check if it was set.
# You only need to explicitly check if the flag was set if you care whether the user
# explicitly passed the empty string as the argument.
#
# Otherwise, call one of the flag_*arg functions:
#
# If a flag requires an argument, call flag_reqarg
#   - $FLAGARG is guaranteed to be set after.
# If a flag requires a non empty argument, call flag_nonemptyarg
#   - $FLAGARG is guaranteed to be set to a non empty string after.
# If a flag should not be passed an argument, call flag_noarg
#   - $FLAGARG is guaranteed to be unset after.
#
# And then shift "$FLAGSHIFT"
flag_parse() {
  case "${1-}" in
    -*=*)
      # Remove everything after first equal sign.
      FLAG="${1%%=*}"
      # Remove leading hyphens.
      FLAG="${FLAG#-}"; FLAG="${FLAG#-}"
      FLAGRAW="$(flag_fmt)"
      # Remove everything before first equal sign.
      FLAGARG="${1#*=}"
      FLAGSHIFT=1
      return 0
      ;;
    -)
      FLAGSHIFT=0
      return 1
      ;;
    --)
      FLAGSHIFT=1
      return 1
      ;;
    -*)
      # Remove leading hyphens.
      FLAG="${1#-}"; FLAG="${FLAG#-}"
      FLAGRAW=$(flag_fmt)
      unset FLAGARG
      FLAGSHIFT=1
      if [ $# -gt 1 ]; then
        case "$2" in
          -)
            FLAGARG="$2"
            FLAGSHIFT=2
            ;;
          -*)
            ;;
          *)
            FLAGARG="$2"
            FLAGSHIFT=2
            ;;
        esac
      fi
      return 0
      ;;
    *)
      FLAGSHIFT=0
      return 1
      ;;
  esac
}

flag_reqarg() {
  if [ "${FLAGARG+x}" != x ]; then
    flag_errusage "flag $FLAGRAW requires an argument"
  fi
}

flag_nonemptyarg() {
  flag_reqarg
  if [ -z "$FLAGARG" ]; then
    flag_errusage "flag $FLAGRAW requires a non-empty argument"
  fi
}

flag_noarg() {
  if [ "$FLAGSHIFT" -eq 2 ]; then
    unset FLAGARG
    FLAGSHIFT=1
  elif [ "${FLAGARG+x}" = x ]; then
    # Means an argument was passed via equal sign as in -$FLAG=$FLAGARG
    flag_errusage "flag $FLAGRAW does not accept an argument"
  fi
}

flag_errusage() {
  caterr <<EOF
$1
Run with --help for usage.
EOF
  return 1
}

flag_fmt() {
  if [ "$(printf %s "$FLAG" | wc -c)" -eq 1 ]; then
    echo "-$FLAG"
  else
    echo "--$FLAG"
  fi
}
#!/bin/sh
if [ "${LIB_RELEASE-}" ]; then
  return 0
fi
LIB_RELEASE=1

ensure_os() {
  if [ -n "${OS-}" ]; then
    # Windows defines OS=Windows_NT.
    if [ "$OS" = Windows_NT ]; then
      OS=windows
    fi
    return
  fi
  uname=$(uname)
  case $uname in
    Linux) OS=linux;;
    Darwin) OS=macos;;
    FreeBSD) OS=freebsd;;
    *) OS=$uname;;
  esac
}

ensure_arch() {
  if [ -n "${ARCH-}" ]; then
    return
  fi
  uname_m=$(uname -m)
  case $uname_m in
    aarch64) ARCH=arm64;;
    x86_64) ARCH=amd64;;
    *) ARCH=$uname_m;;
  esac
}

ensure_goos() {
  if [ -n "${GOOS-}" ]; then
    return
  fi
  ensure_os
  case "$OS" in
    macos) export GOOS=darwin;;
    *) export GOOS=$OS;;
  esac
}

ensure_goarch() {
  if [ -n "${GOARCH-}" ]; then
    return
  fi
  ensure_arch
  case "$ARCH" in
    *) export GOARCH=$ARCH;;
  esac
}

gh_repo() {
  gh repo view --json nameWithOwner --template '{{ .nameWithOwner }}'
}

manpath() {
  if command -v manpath >/dev/null; then
    command manpath
  elif man -w 2>/dev/null; then
    man -w
  else
    echo "${MANPATH-}"
  fi
}

is_writable_dir() {
  mkdir -p "$1" 2>/dev/null
  # directory must exist otherwise -w returns 1 even for paths that should be writable.
  [ -w "$1" ]
}

ensure_prefix() {
  if [ -n "${PREFIX-}" ]; then
    return
  fi
  # The reason for checking whether lib is writable is that on macOS you have /usr/local
  # owned by root but you don't need root to write to its subdirectories which is all we
  # need to do.
  if ! is_writable_dir "/usr/local/lib"; then
    # This also handles M1 Mac's which do not allow modifications to /usr/local even
    # with sudo.
    PREFIX=$HOME/.local
  else
    PREFIX=/usr/local
  fi
}

ensure_prefix_sh_c() {
  ensure_prefix

  sh_c="sh_c"
  # The reason for checking whether lib is writable is that on macOS you have /usr/local
  # owned by root but you don't need root to write to its subdirectories which is all we
  # need to do.
  if ! is_writable_dir "$PREFIX/lib"; then
    sh_c="sudo_sh_c"
  fi
}
#!/bin/sh
if [ -n "${D2_RELEASE_CHECKSUM-}" ]; then
  return 0
fi
D2_RELEASE_CHECKSUM=1

sha256_file() {
  if command -v sha256sum >/dev/null 2>&1; then
    sha256sum "$1" | awk '{ print $1 }'
  elif command -v shasum >/dev/null 2>&1; then
    shasum -a 256 "$1" | awk '{ print $1 }'
  elif command -v openssl >/dev/null 2>&1; then
    openssl dgst -sha256 "$1" | awk '{ print $NF }'
  else
    echo >&2 "sha256sum, shasum, or openssl is required to verify release downloads"
    return 1
  fi
}

release_asset_digest_from_json() {
  ASSET_NAME=$1
  awk -v asset="$ASSET_NAME" '
    /^[[:space:]]*"name":[[:space:]]*/ {
      value = $0
      sub(/^[^:]*:[[:space:]]*"/, "", value)
      sub(/"[,[:space:]]*$/, "", value)
      found = value == asset
      next
    }
    found && /^[[:space:]]*"digest":[[:space:]]*/ {
      value = $0
      if (value ~ /^[^:]*:[[:space:]]*null[,[:space:]]*$/) {
        print "unavailable"
        exit
      }
      original = value
      sub(/^[^:]*:[[:space:]]*"sha256:/, "", value)
      if (value == original) {
        exit
      }
      sub(/"[,[:space:]]*$/, "", value)
      print value
      exit
    }
  '
}

release_asset_sha256() {
  REPOSITORY=$1
  RELEASE_VERSION=$2
  ASSET_NAME=$3
  RELEASE_INFO=$(mktempd)/release.json
  RELEASE_INFO_URL="https://api.github.com/repos/$REPOSITORY/releases/tags/$RELEASE_VERSION"
  DRY_RUN= fetch_gh "$RELEASE_INFO_URL" "$RELEASE_INFO" 'application/vnd.github+json'
  EXPECTED_SHA256=$(release_asset_digest_from_json "$ASSET_NAME" <"$RELEASE_INFO")
  if [ "$EXPECTED_SHA256" = unavailable ]; then
    return 0
  fi
  EXPECTED_SHA256=$(printf '%s' "$EXPECTED_SHA256" | tr '[:upper:]' '[:lower:]')
  if ! printf '%s\n' "$EXPECTED_SHA256" | grep -Eq '^[0-9a-f]{64}$'; then
    echo >&2 "$ASSET_NAME does not have a valid GitHub SHA-256 digest"
    return 1
  fi
  printf '%s\n' "$EXPECTED_SHA256"
}

verify_sha256() {
  FILE=$1
  EXPECTED_SHA256=$2
  ACTUAL_SHA256=$(sha256_file "$FILE")
  ACTUAL_SHA256=$(printf '%s' "$ACTUAL_SHA256" | tr '[:upper:]' '[:lower:]')
  if [ "$ACTUAL_SHA256" != "$EXPECTED_SHA256" ]; then
    echo >&2 "$FILE has SHA-256 $ACTUAL_SHA256, expected $EXPECTED_SHA256"
    return 1
  fi
}

fetch_release_asset() {
  REPOSITORY=$1
  RELEASE_VERSION=$2
  ASSET_NAME=$3
  ASSET_URL=$4
  DESTINATION=$5
  STAGED_ARCHIVE=$6
  EXPECTED_SHA256=${7-}

  if [ -n "${DRY_RUN-}" ]; then
    if [ -n "$EXPECTED_SHA256" ]; then
      log "would verify $ASSET_NAME against the SHA-256 pinned in this installer"
    else
      log "would check the GitHub SHA-256 digest for $ASSET_NAME when available"
    fi
    return
  fi

  if [ -z "$EXPECTED_SHA256" ]; then
    EXPECTED_SHA256=$(release_asset_sha256 "$REPOSITORY" "$RELEASE_VERSION" "$ASSET_NAME")
  fi
  if [ -z "$EXPECTED_SHA256" ]; then
    warn "GitHub does not provide a SHA-256 digest for $ASSET_NAME; continuing without checksum verification for compatibility with legacy releases"
  elif [ -e "$DESTINATION" ]; then
    cp "$DESTINATION" "$STAGED_ARCHIVE"
    if verify_sha256 "$STAGED_ARCHIVE" "$EXPECTED_SHA256"; then
      log "reusing verified $DESTINATION"
      return
    fi
    warn "discarding cached $ASSET_NAME after checksum verification failed"
    rm -f "$DESTINATION"
  fi
  fetch_gh "$ASSET_URL" "$DESTINATION" 'application/octet-stream'
  cp "$DESTINATION" "$STAGED_ARCHIVE"
  if [ -n "$EXPECTED_SHA256" ]; then
    verify_sha256 "$STAGED_ARCHIVE" "$EXPECTED_SHA256"
    log "verified $ASSET_NAME ($EXPECTED_SHA256)"
  fi
}
#!/bin/sh

# Print a verifier executable, using the caller's private temporary directory
# for a one-install copy when a compatible GitHub CLI is unavailable.
installer_gh() (
  # gh 2.102.0 fixed exact workflow and case-sensitive ref matching
  # (GHSA-wjmr-j3rp-mh2g and GHSA-4mq3-hpgx-9cx8).
  if gh --version 2>/dev/null | awk '
    NR == 1 && $1 == "gh" && $2 == "version" && $3 ~ /^[0-9]+\.[0-9]+\.[0-9]+$/ {
      split($3, v, ".")
      supported = v[1] > 2 || (v[1] == 2 && v[2] >= 102)
    }
    END { exit !supported }
  ' && gh attestation verify --bundle /dev/null --source-ref test --signer-workflow test --help >/dev/null 2>&1; then
    command -v gh
    return
  fi

  version=2.105.0
  # The verifier must run on this host even when OS/ARCH select a different D2 archive.
  host_os=$(uname -s) || return 1
  host_arch=$(uname -m) || return 1
  case "$host_os" in
    Linux) host_os=linux ;;
    Darwin) host_os=macos ;;
    MSYS*|MINGW*|CYGWIN*) host_os=windows ;;
  esac
  case "$host_arch" in
    x86_64|amd64) host_arch=amd64 ;;
    aarch64|arm64) host_arch=arm64 ;;
  esac
  # From cli/cli's immutable release and gh_2.105.0_checksums.txt. Pin the
  # archive here so it is authenticated before any of its code can run.
  case "$host_os-$host_arch" in
    linux-amd64)   digest=79e7ab5db738c48777b696e374f8b428f0647debfb424f44d2f426370407fe2f ;;
    linux-arm64)   digest=b1278c75107423d818f1937fd92cafc9e5e9b606631568f68d7fb816f5885a02 ;;
    macos-amd64)   digest=23602cbccbbdc6285a8520745b714cb927ce2ca621779373c2a20cd8e33fda66 ;;
    macos-arm64)   digest=2a5d03103ae444927383b93d9ffd65579a26e2eb900ce1cf11f55258d5319ded ;;
    windows-amd64) digest=8813a72c899900afaa10e3fec8fbc64b908c89dbfe837e95ed2fa500fc140627 ;;
    windows-arm64) digest=5282a09c7757210c6e2dfb11a56b11e14e646df9b3b6a49f155465f5f881c3b7 ;;
    *) echo >&2 "No pinned GitHub CLI for $host_os-$host_arch. Install gh 2.102.0 or later."; return 1 ;;
  esac

  executable=gh
  case "$host_os" in
    linux)   archive="gh_${version}_linux_${host_arch}.tar.gz"; member="${archive%.tar.gz}/bin/gh" ;;
    macos)   archive="gh_${version}_macOS_${host_arch}.zip"; member="${archive%.zip}/bin/gh" ;;
    windows) archive="gh_${version}_windows_${host_arch}.zip"; member=bin/gh.exe; executable=gh.exe ;;
  esac

  echo >&2 "Downloading GitHub CLI $version to verify D2 release provenance"
  curl -qfsSL --proto '=https' --proto-redir '=https' -o "$1/$archive" \
    "https://github.com/cli/cli/releases/download/v$version/$archive" || return 1
  verify_sha256 "$1/$archive" "$digest" || return 1

  if [ "$host_os" = linux ]; then
    tar -xzOf "$1/$archive" "$member"
  elif command -v unzip >/dev/null 2>&1; then
    unzip -p "$1/$archive" "$member"
  else
    bsdtar -xOf "$1/$archive" "$member"
  fi >"$1/$executable" || return 1
  chmod 700 "$1/$executable" || return 1
  printf '%s\n' "$1/$executable"
)
